/* Reel v2 motion data and pure functions of time (MOTION.md).
 * Needs physics.js and timing.js (generated by scripts/timing.py) loaded first.
 * Every composition reads the same tracks, so the shell, the pill, the camera, the cursor and each
 * state's content agree on every frame. World coordinates: the 1080×1920 canvas before the camera.
 */
(function (root) {
  var P = root.Physics;
  var T = root.Timing;
  var A = T.A;
  var S = T.S;
  var END = T.END;
  var W = 1080;
  var H = 1920;
  var SCREEN = { x: 540, y: 880 }; // the world point the camera centres on lands here
  var ORDER = ["card", "chat", "weeks", "disc", "list", "busy", "toggle", "timeline", "client", "price", "parlana", "inbox", "split", "cta", "loop"];

  function beatNear(t) {
    var b = T.BEATS.reduce(function (best, x) {
      return Math.abs(x - t) < Math.abs(best - t) ? x : best;
    }, T.BEATS[0]);
    return Math.abs(b - t) <= 0.15 ? b : t;
  }
  function beatAfter(t, n) {
    var i = T.BEATS.findIndex(function (x) {
      return x >= t - 1e-6;
    });
    return T.BEATS[Math.min(T.BEATS.length - 1, i + (n || 0))];
  }

  // ── the actions (taps and holds), each on its word, pulled onto the beat when close ──────────
  var TAP = {
    stamp: beatNear(A.llego),
    carla: beatNear(A.recordatorios1),
    diego: beatNear(A.clientes1),
    knob: beatNear(A.automaticamente + 0.1),
    confirm: beatNear(A.confirmar),
    cta: beatNear(A.citasCta + 0.15),
  };
  var HOLD = {
    stamp: [TAP.stamp - 0.45, TAP.stamp], // v3: the cursor lifts "Pendiente", carries it and slams it down as the stamp
    weeks: [beatNear(A.tampoco), A.primera + 0.35],
    hour: [beatNear(A.tiempo), A.reservaste],
    chipA: [S.timeline, A.anterior + 0.2],
    chipB: [beatNear(A.unas), A.antes + 0.1],
    slider: [A.boliviano + 0.35, A.siete + 0.2],
  };

  // The send button presses itself (state 10): one message out every eighth note.
  var AUTOSEND = [0, 1, 2, 3, 4, 5, 6].map(function (i) {
    return A.sinTener + i * 0.24;
  });

  // ── the shape ─────────────────────────────────────────────────────────────────────────────────
  var SHELL = [
    { t: 0, rect: [140, 600, 800, 560], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" }, // card 10:00
    { t: A.listo - 0.35, rect: [140, 600, 800, 820], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" }, // grows the checklist
    { t: S.chat, rect: [170, 450, 740, 840], r: 56, fill: "#EFEAE2", edge: "#D3D1C7" },
    { t: S.weeks, rect: [90, 600, 900, 560], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.disc, rect: [300, 590, 480, 480], r: 240, fill: "#FFFFFF", edge: "#FFFFFF" },
    { t: S.list, rect: [140, 560, 800, 720], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.busy, rect: [170, 420, 740, 880], r: 56, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.toggle, rect: [140, 770, 800, 180], r: 90, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.timeline, rect: [110, 600, 860, 600], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.client, rect: [170, 450, 740, 860], r: 56, fill: "#EFEAE2", edge: "#D3D1C7" },
    { t: S.price, rect: [110, 560, 860, 780], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.parlana, rect: [140, 520, 800, 820], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.inbox, rect: [170, 450, 740, 860], r: 56, fill: "#EFEAE2", edge: "#D3D1C7" },
    { t: S.split, rect: [90, 460, 900, 880], r: 48, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.cta, rect: [140, 620, 800, 600], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" },
    { t: S.loop, rect: [140, 600, 800, 560], r: 40, fill: "#FFFFFF", edge: "#D3D1C7" }, // = the first frame
  ];

  // ── the thread: the appointment's status pill ──────────────────────────────────────────────────
  // face: which label the pill wears (pill.html). fill/edge/ink: its colours.
  var INK = "#2C2C2A";
  var CREAM = "#F6F4EF";
  var GREEN = "#155B3F";
  var LIST_ROW = [740, 870, 1000]; // list rows (state 5)
  var PARL_ROW = [760, 880, 1000, 1120]; // automated list rows (state 11)
  var PILL = [
    { t: 0, rect: [676, 1070, 208, 62], r: 31, fill: "#FFFFFF", edge: "#D3D1C7", face: "pending" },
    { t: TAP.stamp - 0.32, rect: [600, 1370, 320, 100], r: 50, fill: INK, edge: INK, face: "missed" }, // v3: in the air, lands on TAP.stamp
    { t: S.chat, rect: [236, 840, 150, 76], r: 38, fill: "#FFFFFF", edge: "#FFFFFF", face: "dots" },
    { t: A.contesta + 0.05, rect: [236, 850, 108, 56], r: 28, fill: "#FFFFFF", edge: "#E4E1D8", face: "dots" },
    { t: S.weeks, rect: [700, 636, 234, 64], r: 32, fill: INK, edge: INK, face: "count" },
    { t: S.disc, rect: [508, 1050, 64, 40], r: 20, fill: INK, edge: INK, face: null },
    { t: beatNear(A.ingreso), rect: [370, 1032, 340, 84], r: 42, fill: INK, edge: INK, face: "lost" },
    { t: S.list, rect: [818, LIST_ROW[0] + 32, 56, 56], r: 16, fill: "#FFFFFF", edge: "#D3D1C7", face: null },
    { t: TAP.carla, rect: [818, LIST_ROW[0] + 32, 56, 56], r: 16, fill: GREEN, edge: GREEN, face: "tick" },
    { t: TAP.carla + 0.45, rect: [818, LIST_ROW[1] + 32, 56, 56], r: 16, fill: "#FFFFFF", edge: "#D3D1C7", face: null },
    { t: TAP.diego, rect: [818, LIST_ROW[1] + 32, 56, 56], r: 16, fill: GREEN, edge: GREEN, face: "tick" },
    { t: TAP.diego + 0.4, rect: [818, LIST_ROW[2] + 32, 56, 56], r: 16, fill: "#FFFFFF", edge: "#D3D1C7", face: null }, // Juan: unchecked
    { t: S.busy + 0.25, rect: [360, 448, 360, 84], r: 42, fill: INK, edge: INK, face: "island" },
    { t: S.toggle, rect: [734, 822, 76, 76], r: 38, fill: "#FFFFFF", edge: "#E4E1D8", face: null, ball: 1 }, // v3: the token rounds into a ball
    { t: TAP.knob, rect: [802, 822, 76, 76], r: 38, fill: "#FFFFFF", edge: "#E4E1D8", face: null, stretch: 0.45, vsat: 450, ball: 1 },
    // The knob becomes the "Día anterior" chip and rides the cursor to the day before (same spring: locked together).
    { t: S.timeline, rect: [240, 1003, 240, 64], r: 32, fill: GREEN, edge: GREEN, face: "chipA", w: 9, z: 0.85, stretch: 0.12 },
    { t: S.client, rect: [214, 790, 318, 84], r: 42, fill: "#FFFFFF", edge: GREEN, face: "confirm" },
    { t: TAP.confirm, rect: [214, 790, 318, 84], r: 42, fill: GREEN, edge: GREEN, face: "confirmed" },
    { t: S.price, rect: [166, 680, 180, 180], r: 90, fill: GREEN, edge: GREEN, face: "coin" },
    { t: A.mejor, rect: [690, 1236, 224, 76], r: 38, fill: INK, edge: INK, face: "send" },
    { t: S.parlana, rect: [680, PARL_ROW[0] + 28, 220, 60], r: 30, fill: "#FFFFFF", edge: "#D3D1C7", face: null },
    { t: beatNear(A.gestionar), rect: [680, PARL_ROW[0] + 28, 220, 60], r: 30, fill: GREEN, edge: GREEN, face: "ok" },
    { t: beatAfter(A.gestionar, 2), rect: [680, PARL_ROW[1] + 28, 220, 60], r: 30, fill: "#EFEAE2", edge: "#D3D1C7", face: "moved" },
    { t: beatAfter(A.gestionar, 4), rect: [680, PARL_ROW[2] + 28, 220, 60], r: 30, fill: GREEN, edge: GREEN, face: "ok" },
    { t: beatAfter(A.gestionar, 6), rect: [680, PARL_ROW[3] + 28, 220, 60], r: 30, fill: GREEN, edge: GREEN, face: "ok" },
    { t: S.inbox, rect: [690, 800, 150, 76], r: 38, fill: "#E7F0EB", edge: "#E7F0EB", face: "dots" }, // Parlana typing
    { t: beatNear(A.responder), rect: [384, 1010, 140, 64], r: 32, fill: "#FFFFFF", edge: "#D3D1C7", face: "slot" }, // the 11:30 slot
    { t: beatNear(A.consultas) + 0.75, rect: [384, 1010, 140, 64], r: 32, fill: GREEN, edge: GREEN, face: "slotPicked" }, // picked
    { t: beatNear(A.agendar), rect: [214, 1130, 652, 84], r: 42, fill: GREEN, edge: GREEN, face: "booked" },
    { t: S.split, rect: [140, 560, 360, 80], r: 40, fill: INK, edge: INK, face: "island" },
    { t: S.cta, rect: [196, 1010, 688, 110], r: 55, fill: GREEN, edge: GREEN, face: "cta" },
    { t: S.loop, rect: [636, 1070, 248, 62], r: 31, fill: GREEN, edge: GREEN, face: "confirmada" },
  ];

  // ── camera: zoom + world centre per state ──────────────────────────────────────────────────────
  var CAM = [
    { t: 0, z: 1.2, x: 540, y: 890 },
    { t: A.listo - 0.35, z: 1.0, x: 540, y: 1010 },
    { t: S.chat, z: 1.2, x: 540, y: 870 },
    { t: S.weeks, z: 1.08, x: 540, y: 880 },
    { t: S.disc, z: 1.3, x: 540, y: 860 },
    { t: S.list, z: 1.15, x: 540, y: 920 },
    { t: S.busy, z: 1.2, x: 540, y: 905 }, // v3: a little higher, so Juan's row falls clear of the captions
    { t: S.toggle, z: 1.22, x: 540, y: 860 },
    { t: S.timeline, z: 1.15, x: 540, y: 900 },
    { t: S.client, z: 1.2, x: 540, y: 880 },
    { t: S.price, z: 1.12, x: 540, y: 950 },
    { t: S.parlana, z: 1.12, x: 540, y: 930 },
    { t: S.inbox, z: 1.2, x: 540, y: 880 },
    { t: S.split, z: 1.08, x: 540, y: 900 },
    { t: S.cta, z: 1.15, x: 540, y: 910 },
    { t: TAP.cta, z: 1.22, x: 540, y: 980 }, // v3: a push towards the button as it goes down
    { t: S.loop, z: 1.2, x: 540, y: 890 },
  ];

  // ── cursor: world targets; it springs between them and drives every change ─────────────────────
  var CUR0 = { x: 900, y: 1300 };
  var CUR = [
    { t: 1.2, x: 248, y: 1112 }, // to the empty chair
    { t: A.paso - 0.6, x: 866, y: 1110 }, // to "Pendiente" (v3: by its end, so the hand never covers the label)
    { t: TAP.stamp - 0.32, x: 895, y: 1440, w: 15, z: 0.72 }, // v3: carries it on the pill's own spring (locked together)
    { t: S.chat + 0.2, x: 700, y: 1010 }, // waits on the chat
    { t: S.weeks + 0.05, x: 780, y: 930 }, // grabs the weeks
    { t: HOLD.weeks[0] + 0.05, x: 330, y: 930, w: 5, z: 1 }, // drags them
    { t: S.disc + 0.2, x: 540, y: 835 }, // the hour
    { t: S.list + 0.1, x: 846, y: LIST_ROW[0] + 60 }, // Carla's box
    { t: TAP.carla + 0.3, x: 846, y: LIST_ROW[1] + 60 }, // Diego's box
    { t: TAP.diego + 0.35, x: 900, y: LIST_ROW[2] + 140 }, // Juan's stays unticked
    { t: A.implica, x: 540, y: 1198 }, // reaches for Juan's reminder…
    { t: A.negocio + 0.15, x: 540, y: 1238 },
    { t: A.tiempo2 + 0.15, x: 540, y: 1276 }, // …it keeps slipping…
    { t: A.alguno + 0.5, x: 640, y: 1150 }, // …gives up
    { t: S.toggle + 0.5, x: 772, y: 860 }, // the knob
    { t: S.timeline, x: 360, y: 1035, w: 9, z: 0.85 }, // carries "Día anterior" to the day before
    { t: HOLD.chipA[1] - 0.15, x: 820, y: 752, w: 16 }, // grabs "Unas horas antes"
    { t: HOLD.chipB[0], x: 720, y: 1035, w: 9, z: 0.85 }, // drops it a few hours before
    { t: S.client + 0.6, x: 373, y: 832 }, // to "Confirmar"
    { t: A.boliviano - 0.4, x: 166, y: 1066 }, // the slider's handle
    { t: HOLD.slider[0] + 0.05, x: 975, y: 1066, w: 7, z: 1 }, // drags past the end
    { t: A.sinTener, x: 905, y: 1430 }, // lets go: it sends on its own (v3: parked inside the frame)
    { t: S.split + 0.4, x: 300, y: 760 }, // stays on "En tu local"
    { t: S.cta + 0.5, x: 900, y: 1300 },
    { t: A.comenta - 0.55, x: 300, y: 1065 }, // to the CTA
    { t: S.loop + 0.1, x: CUR0.x, y: CUR0.y, w: 6, z: 1 }, // home, at rest, for the loop
  ];
  function cursorTrack(axis) {
    return P.track(CUR0[axis], CUR.map(function (k) {
      return { t: k.t, v: k[axis], w: k.w || 10, z: k.z || 0.9 };
    }));
  }
  var curX = cursorTrack("x");
  var curY = cursorTrack("y");

  // ── direct manipulation ─────────────────────────────────────────────────────────────────────────
  function dragRelease(hold, grabAxis, target, w, z, from) {
    var relX = grabAxis(hold[1]) - grabAxis(hold[0]);
    var relV = P.velocity(grabAxis, hold[1]);
    return function (t) {
      if (t < hold[0]) return from || 0;
      if (t < hold[1]) return (from || 0) + grabAxis(t) - grabAxis(hold[0]);
      return P.release((from || 0) + relX, relV, target, w, z, t - hold[1]);
    };
  }
  var weeksX = dragRelease(HOLD.weeks, curX, -520, 9, 0.8); // the weeks strip (state 3)
  function missedCount(t) {
    var x = weeksX(t);
    return 3 + (x <= -130 ? 1 : 0) + (x <= -390 ? 1 : 0);
  }
  // The slider (state 9): follows the hand up to the end, rubber-bands past it, springs back on release.
  var SL = { x0: 166, x1: 914 };
  function sliderX(t) {
    var h = HOLD.slider;
    var raw = function (u) {
      var x = curX(u);
      return x <= SL.x1 ? Math.max(SL.x0, x) : SL.x1 + (x - SL.x1) * 0.35;
    };
    if (t < h[0]) return SL.x0;
    if (t < h[1]) return raw(t);
    return P.release(raw(h[1]), P.velocity(raw, h[1]), SL.x1, 14, 0.7, t - h[1]);
  }
  function sliderValue(t) {
    var x = Math.min(SL.x1, sliderX(t));
    return 1 + Math.round(((x - SL.x0) / (SL.x1 - SL.x0)) * 6);
  }

  // ── shared tracks ───────────────────────────────────────────────────────────────────────────────
  function colorTrack(list, key, w) {
    return P.color(list.map(function (s) {
      return { t: s.t, c: P.hex(s[key]) };
    }), w || 22);
  }
  var shell = P.body(SHELL, { w: 12, z: 0.78, stretch: 0.05, vsat: 1500 });
  var cam = ["z", "x", "y"].map(function (k) {
    return P.track(CAM[0][k], CAM.slice(1).map(function (c) {
      return { t: c.t, v: c[k], w: 6.5, z: 0.92 };
    }));
  });
  function camera(t) {
    return { z: cam[0](t), x: cam[1](t), y: cam[2](t) };
  }
  function worldTransform(t) {
    var c = camera(t);
    return "translate(" + (SCREEN.x - c.x * c.z).toFixed(2) + "px, " + (SCREEN.y - c.y * c.z).toFixed(2) + "px) scale(" + c.z.toFixed(4) + ")";
  }
  function inset(g, pad) {
    return "inset(" + (g.t + pad).toFixed(2) + "px " + (W - g.r + pad).toFixed(2) + "px " + (H - g.b + pad).toFixed(2) + "px " + (g.l + pad).toFixed(2) + "px round " + Math.max(0, g.rad - pad).toFixed(2) + "px)";
  }
  function toScreen(t, wx, wy) {
    var c = camera(t);
    return { x: SCREEN.x + (wx - c.x) * c.z, y: SCREEN.y + (wy - c.y) * c.z };
  }

  // ── content timing helpers ──────────────────────────────────────────────────────────────────────
  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }
  function smooth(v) {
    v = clamp01(v);
    return v * v * (3 - 2 * v);
  }
  // A state's window, and how its host clip is mounted (index.html is generated from this).
  function stateSpan(name) {
    var i = ORDER.indexOf(name);
    return [S[name], i + 1 < ORDER.length ? S[ORDER[i + 1]] : END];
  }
  function hostWindow(name) {
    var s = stateSpan(name);
    var a = Math.max(0, s[0] - 0.05);
    var b = Math.min(END, s[1] + 0.12);
    return [Math.round(a * 1000) / 1000, Math.round((b - a) * 1000) / 1000];
  }
  // Content of a state: in on the morph's second half, out before the next morph; blur + lift.
  function vis(t, start, end) {
    var vin = start <= 0 ? 1 : smooth((t - (start + 0.06)) / 0.22);
    var vout = end >= END ? 1 : 1 - smooth((t - (end - 0.12)) / 0.14);
    return { v: Math.min(vin, vout), vin: vin, vout: vout };
  }
  function apply(el, t, start, end, lift) {
    var s = vis(t, start, end);
    el.style.opacity = s.v.toFixed(3);
    el.style.filter = s.v >= 0.999 ? "none" : "blur(" + ((1 - s.v) * 8).toFixed(2) + "px)";
    if (lift !== false) el.style.transform = "translateY(" + ((1 - s.vin) * 14 - (1 - s.vout) * 14).toFixed(2) + "px)";
    return s.v;
  }
  // An element that pops in at `at` (spring scale + quick fade), optionally away at `out`.
  function pop(el, t, at, out) {
    var k = P.step(t - at, 18, 0.72);
    var o = clamp01((t - at) / 0.08);
    if (out !== undefined) o = Math.min(o, 1 - smooth((t - out) / 0.15));
    el.style.opacity = o.toFixed(3);
    el.style.transform = "scale(" + (0.82 + 0.18 * k).toFixed(4) + ")";
  }
  function fadeAt(el, t, at, dur) {
    var v = smooth((t - at) / (dur || 0.2));
    el.style.opacity = v.toFixed(3);
    return v;
  }
  // Press compression: 1 at full press. Taps: 80 ms down, spring back; holds: down while held.
  function press(t) {
    var k = 0;
    Object.keys(TAP).forEach(function (n) {
      var a = TAP[n];
      if (t >= a && t < a + 0.08) k = Math.max(k, (t - a) / 0.08);
      else if (t >= a + 0.08 && t < a + 0.3) k = Math.max(k, 1 - P.step(t - a - 0.08, 22, 0.8));
    });
    Object.keys(HOLD).forEach(function (n) {
      var h = HOLD[n];
      if (t >= h[0] && t < h[1]) k = Math.max(k, clamp01((t - h[0]) / 0.07));
      else if (t >= h[1] && t < h[1] + 0.25) k = Math.max(k, 1 - P.step(t - h[1], 22, 0.8));
    });
    return k;
  }

  // Mount a state composition: one driver tween that renders global time = host start + local time.
  function mountState(name, rootEl, worldEl, clipEl, render) {
    var hw = hostWindow(name);
    var span = stateSpan(name);
    var clock = { t: 0 };
    var tl = root.gsap.timeline({ paused: true });
    function frame(local) {
      var t = hw[0] + local;
      worldEl.style.transform = root.Reel.worldTransform(t); // late-bound: view.js swaps in the 3D camera
      clipEl.style.clipPath = inset(shell(t), 3);
      render(t, span);
    }
    tl.fromTo(clock, { t: 0 }, { t: hw[1], duration: hw[1], ease: "none", onUpdate: function () { frame(clock.t); } }, 0);
    frame(0);
    return tl;
  }

  // Mount a full-length composition (shell, pill, cursor, captions): local time = global time.
  function mountFull(render) {
    var clock = { t: 0 };
    var tl = root.gsap.timeline({ paused: true });
    tl.fromTo(clock, { t: 0 }, { t: END, duration: END, ease: "none", onUpdate: function () { render(clock.t); } }, 0);
    render(0);
    return tl;
  }

  root.Reel = {
    W: W, H: H, A: A, S: S, END: END, ORDER: ORDER, BEATS: T.BEATS, MEDIA_START: T.MEDIA_START,
    TAP: TAP, HOLD: HOLD, AUTOSEND: AUTOSEND, SHELL: SHELL, PILL: PILL, CAM: CAM, LIST_ROW: LIST_ROW, PARL_ROW: PARL_ROW, SL: SL,
    beatNear: beatNear, beatAfter: beatAfter, curX: curX, curY: curY, weeksX: weeksX, missedCount: missedCount,
    sliderX: sliderX, sliderValue: sliderValue, shell: shell, camera: camera, worldTransform: worldTransform,
    inset: inset, toScreen: toScreen, colorTrack: colorTrack, clamp01: clamp01, smooth: smooth, stateSpan: stateSpan,
    hostWindow: hostWindow, vis: vis, apply: apply, pop: pop, fadeAt: fadeAt, press: press, mountState: mountState, mountFull: mountFull,
  };
})(typeof window !== "undefined" ? window : globalThis);
